// DrillGraphPage — a whole graph workspace as ONE data prop (a-drill-graph-is-one-wire-shape-for-every-
// workspace). The graph arrives in the DrillGraph shape (`@/shared/ui/pages/drillGraph`): tabs, each
// holding levels keyed by the workspace's own drill path, each level ALREADY LAID OUT by the desktop's
// grouping + layout functions. This page draws the current level at those positions — it never
// re-lays out, which is the difference from NetworkPage — and owns only the view state: which tab,
// which path, which node is selected.
//
// It is what a paired phone renders for every graph workspace (epic-the-phone-shows-every-desktop-
// page), and the desktop registers it too, so a `mobile.tab.*` record previews in the Design Studio as
// the same picture. Click selects a node and opens its facts; double-click, or "Open" in the
// inspector, drills into the level a node opens. A tab or path that disappears in a later graph falls
// back to the nearest surviving ancestor rather than a blank (`resolveDrill`).
import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Text } from "@/shared/ui/typography/Text";
import { Button } from "@/shared/ui/controls/Button";
import { IconButton } from "@/shared/ui/controls/IconButton";
import { BackButton } from "@/shared/ui/controls/BackButton";
import { SegmentedControl } from "@/shared/ui/controls/SegmentedControl";
import { KeyValueList, type KeyValueItem } from "@/shared/ui/data/KeyValueList";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import {
  ROOT_PATH, breadcrumb, isDrillable, levelWorld, parentPath, resolveDrill, type DrillGraph, type DrillNode,
} from "@/shared/ui/pages/drillGraph";

export interface DrillGraphPageProps {
  /** Page title (the toolbar row). */
  title: ReactNode;
  /** Dimmed hint after the title. */
  hint?: ReactNode;
  /** The whole graph: tabs → levels by drill path → laid-out nodes and edges. */
  graph: DrillGraph;
  /** The tab shown first. Default: the first tab. */
  defaultTab?: string;
  /** The drill path shown first. Default: the root. */
  defaultPath?: string;
  /** Inspector width in px when a node is selected. Default 300. */
  inspectorWidth?: number;
  /** Extra class on the root (a page scoping hook). */
  className?: string;
}

const ELLIPSIS: CSSProperties = { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" };

export function DrillGraphPage({
  title, hint, graph, defaultTab, defaultPath = ROOT_PATH, inspectorWidth = 300, className,
}: DrillGraphPageProps) {
  const [wantTab, setWantTab] = useState<string | null>(defaultTab ?? null);
  // Each tab keeps its own drill path, as every desktop graph workspace does.
  const [paths, setPaths] = useState<Record<string, string>>(() => (defaultTab ? { [defaultTab]: defaultPath } : {}));
  const [selected, setSelected] = useState<string | null>(null);

  const firstTab = graph.tabs[0]?.id ?? null;
  const tabId = wantTab ?? firstTab;
  const resolved = useMemo(
    () => resolveDrill(graph, tabId, (tabId && paths[tabId]) ?? (tabId === defaultTab ? defaultPath : ROOT_PATH)),
    [graph, tabId, paths, defaultTab, defaultPath],
  );

  const world = useMemo(() => (resolved ? levelWorld(resolved.level) : { w: 0, h: 0 }), [resolved]);
  const vp = useGraphViewport(world);
  const { fit } = vp;
  useEffect(() => { fit(); }, [fit, resolved?.tab.id, resolved?.path, world.w, world.h]);

  if (!resolved) {
    return <EmptyState title="Nothing to draw" description="This graph carries no tabs yet." />;
  }
  const { tab, path, level } = resolved;
  const byId = new Map(level.nodes.map((n) => [n.id, n]));
  const selectedNode = selected ? byId.get(selected) : undefined;

  const go = (next: string) => {
    setPaths((p) => ({ ...p, [tab.id]: next }));
    setSelected(null);
  };
  const drill = (node: DrillNode) => {
    if (isDrillable(tab, node) && node.drillTo !== undefined) go(node.drillTo);
  };

  const inspector = (node: DrillNode): ReactNode => {
    const facts: KeyValueItem[] = [
      { k: "id", v: node.id },
      ...(node.kind ? [{ k: "kind", v: node.kind }] : []),
      ...(node.meta ? [{ k: "meta", v: node.meta }] : []),
      ...(node.facts ?? []),
    ];
    return (
      <Stack gap={12}>
        <Text size="md" weight={600}>{node.label}</Text>
        <KeyValueList mono items={facts} />
        {isDrillable(tab, node) && <Button onClick={() => drill(node)}>Open</Button>}
      </Stack>
    );
  };

  return (
    <GraphCanvas
      vp={vp} world={world} grid className={className}
      toolbar={
        <>
          {path !== ROOT_PATH && (
            <BackButton variant="icon" aria-label="Back one level" onClick={() => go(parentPath(path))} />
          )}
          <Text size="sm" weight={600}>{title}</Text>
          {hint != null && <Text size="xs" tone="dim">{hint}</Text>}
          <Row gap={4} align="center">
            {breadcrumb(tab, path).map((c, i, all) => (
              <Text key={c.path} size="xs" tone={i === all.length - 1 ? undefined : "dim"}
                style={{ cursor: i === all.length - 1 ? "default" : "pointer" }}
                onClick={i === all.length - 1 ? undefined : () => go(c.path)}>
                {i > 0 ? `/ ${c.label}` : c.label}
              </Text>
            ))}
          </Row>
          {graph.tabs.length > 1 && (
            <SegmentedControl options={graph.tabs.map((t) => ({
              label: t.label, on: t.id === tab.id, onClick: () => { setWantTab(t.id); setSelected(null); },
            }))} />
          )}
          <Spacer />
          <ZoomControls vp={vp} />
          <IconButton aria-label="fit graph" title="Fit" onClick={() => fit()}>⤢</IconButton>
        </>
      }
      inspector={selectedNode ? (
        <Box pad={16} style={{
          flex: `0 0 ${inspectorWidth}px`, width: inspectorWidth, minWidth: 0,
          borderLeft: "1px solid var(--border-soft)", overflowY: "auto",
        }}>
          {inspector(selectedNode)}
        </Box>
      ) : undefined}
    >
      <svg width={world.w} height={world.h}
        style={{ position: "absolute", left: 0, top: 0, pointerEvents: "none", overflow: "visible" }}>
        {level.edges.map((e, i) => {
          const a = byId.get(e.from), b = byId.get(e.to);
          if (!a || !b) return null;
          const g = graphEdge(a, b);
          return (
            <g key={e.id ?? `${e.from}->${e.to}#${i}`}>
              <path d={g.d} stroke="var(--border)" strokeWidth={1.5} fill="none" />
              <path d={g.arrow} fill="var(--border)" />
            </g>
          );
        })}
      </svg>
      {level.nodes.map((node) => {
        const isSelected = selected === node.id;
        const opens = isDrillable(tab, node);
        return (
          // data-node: the canvas ignores pans/backdrop-clicks that start on a node (#2208).
          <Stack key={node.id} data-node={node.id} data-selected={isSelected || undefined}
            data-drillable={opens || undefined}
            gap={2} justify="center"
            onClick={() => setSelected(node.id)}
            onDoubleClick={() => drill(node)}
            style={{
              position: "absolute", left: node.x, top: node.y, width: node.w, height: node.h,
              padding: "0 12px", borderRadius: 8, cursor: "pointer",
              background: isSelected ? "var(--accent-soft)" : "var(--bg-elev)",
              border: `1px ${opens ? "double" : "solid"} ${isSelected ? "var(--accent)" : "var(--border)"}`,
            }}
          >
            <Text size={12} weight={600} style={ELLIPSIS}>{node.label}</Text>
            {node.meta && <Text size={10} tone="dim" mono style={ELLIPSIS}>{node.meta}</Text>}
          </Stack>
        );
      })}
    </GraphCanvas>
  );
}

