// DrillGraphPage (a-drill-graph-is-one-wire-shape-for-every-workspace) — draws a pre-laid-out level at the
// DESKTOP's positions, switches tabs, drills and steps back, and falls back rather than blanking.
import { describe, it, expect } from "vitest";
import { render, screen, fireEvent } from "@testing-library/react";
import { DrillGraphPage } from "@/shared/ui/pages/DrillGraphPage";
import type { DrillGraph, DrillNode } from "@/shared/ui/pages/drillGraph";

const box = (id: string, x: number, y: number, extra: Partial<DrillNode> = {}): DrillNode =>
  ({ id, label: `L-${id}`, x, y, w: 120, h: 40, ...extra });

const GRAPH: DrillGraph = {
  tabs: [
    {
      id: "rust", label: "Rust",
      levels: {
        "": {
          nodes: [box("crate:a", 10, 20, { drillTo: "crate:a", meta: "12 impls" }), box("crate:b", 300, 20)],
          edges: [{ from: "crate:a", to: "crate:b" }],
        },
        "crate:a": { label: "a", nodes: [box("fn-one", 5, 5, { facts: [{ k: "lines", v: "40" }] })], edges: [] },
      },
    },
    { id: "ts", label: "TypeScript", levels: { "": { nodes: [box("mod", 0, 0)], edges: [] } } },
  ],
};

const card = (c: HTMLElement, id: string) => c.querySelector(`[data-node="${id}"]`) as HTMLElement | null;

describe("DrillGraphPage", () => {
  it("draws the root level at the positions the graph carries — no re-layout", () => {
    const { container } = render(<DrillGraphPage title="Algorithms" graph={GRAPH} />);
    expect(container.querySelectorAll("[data-node]")).toHaveLength(2);
    const a = card(container, "crate:a")!;
    expect([a.style.left, a.style.top, a.style.width]).toEqual(["10px", "20px", "120px"]);
    expect(container.querySelectorAll("svg g")).toHaveLength(1);
    expect(a.dataset.drillable).toBe("true");
    expect(card(container, "crate:b")!.dataset.drillable).toBeUndefined();
  });

  it("double-click drills into the level a node opens, and back returns to the root", () => {
    const { container } = render(<DrillGraphPage title="Algorithms" graph={GRAPH} />);
    fireEvent.doubleClick(card(container, "crate:a")!);
    expect(card(container, "fn-one")).not.toBeNull();
    expect(card(container, "crate:a")).toBeNull();
    fireEvent.click(screen.getByLabelText("Back one level"));
    expect(card(container, "crate:a")).not.toBeNull();
  });

  it("a non-drillable node only selects: its facts open in the inspector, and there is no Open", () => {
    const { container } = render(<DrillGraphPage title="Algorithms" graph={GRAPH} />);
    fireEvent.doubleClick(card(container, "crate:b")!);
    expect(card(container, "crate:b")).not.toBeNull();
    fireEvent.click(card(container, "crate:b")!);
    // The label now shows twice: on the card, and as the inspector heading.
    expect(screen.getAllByText("L-crate:b")).toHaveLength(2);
    expect(screen.queryByRole("button", { name: "Open" })).toBeNull();
  });

  it("Open in the inspector drills too, and the facts the graph carries are shown", () => {
    const { container } = render(<DrillGraphPage title="Algorithms" graph={GRAPH} />);
    fireEvent.click(card(container, "crate:a")!);
    fireEvent.click(screen.getByRole("button", { name: "Open" }));
    fireEvent.click(card(container, "fn-one")!);
    expect(screen.getByText("lines")).toBeInTheDocument();
    expect(screen.getByText("40")).toBeInTheDocument();
  });

  it("switches tabs, and each tab keeps its own drill path", () => {
    const { container } = render(<DrillGraphPage title="Algorithms" graph={GRAPH} />);
    fireEvent.doubleClick(card(container, "crate:a")!);
    fireEvent.click(screen.getByText("TypeScript"));
    expect(card(container, "mod")).not.toBeNull();
    fireEvent.click(screen.getByText("Rust"));
    expect(card(container, "fn-one")).not.toBeNull();
  });

  it("a starting path the graph does not carry falls back to its nearest ancestor, never a blank", () => {
    const { container } = render(
      <DrillGraphPage title="Algorithms" graph={GRAPH} defaultTab="rust" defaultPath="crate:a/gone" />,
    );
    expect(card(container, "fn-one")).not.toBeNull();
  });

  it("says so when there is nothing to draw", () => {
    render(<DrillGraphPage title="Algorithms" graph={{ tabs: [] }} />);
    expect(screen.getByText("Nothing to draw")).toBeInTheDocument();
  });
});
